import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.sql.*;

public class AdminSettingsFrame extends JInternalFrame {
    private final JTextField usernameField=new JTextField(Session.getUsername(),20);
    private final JPasswordField currentPassword=new JPasswordField(20),newPassword=new JPasswordField(20),confirmPassword=new JPasswordField(20);
    public AdminSettingsFrame(){setTitle("Admin Settings");setSize(520,430);setDefaultCloseOperation(JInternalFrame.DISPOSE_ON_CLOSE);
        JPanel root=new JPanel(new BorderLayout(12,12));root.setBackground(AppTheme.BG);root.setBorder(new EmptyBorder(22,22,22,22));JPanel head=new JPanel(new GridLayout(2,1,0,5));head.setOpaque(false);head.add(AppTheme.title("Admin Settings"));JLabel sub=new JLabel("Update the administrator username or password");sub.setForeground(AppTheme.MUTED);head.add(sub);root.add(head,BorderLayout.NORTH);
        JPanel card=AppTheme.card();card.setLayout(new GridLayout(0,2,10,12));card.add(new JLabel("New username"));card.add(usernameField);card.add(new JLabel("Current password"));card.add(currentPassword);card.add(new JLabel("New password"));card.add(newPassword);card.add(new JLabel("Confirm new password"));card.add(confirmPassword);root.add(card,BorderLayout.CENTER);
        JPanel buttons=new JPanel(new FlowLayout(FlowLayout.RIGHT));buttons.setOpaque(false);JButton save=AppTheme.primaryButton("Save Changes"),cancel=AppTheme.button("← Back to Dashboard");buttons.add(save);buttons.add(cancel);root.add(buttons,BorderLayout.SOUTH);setContentPane(root);save.addActionListener(e->saveChanges());cancel.addActionListener(e->dispose());}
    private void saveChanges(){String oldUser=Session.getUsername(),newUser=usernameField.getText().trim(),current=new String(currentPassword.getPassword()),next=new String(newPassword.getPassword()),confirm=new String(confirmPassword.getPassword());if(newUser.isEmpty()||current.isEmpty()){JOptionPane.showMessageDialog(this,"Username and current password are required.");return;}if(!next.isEmpty()&&(next.length()<6||!next.equals(confirm))){JOptionPane.showMessageDialog(this,"New password must be at least 6 characters and both password fields must match.");return;}if(next.isEmpty()&&!newUser.equals(oldUser)){/* username-only change is allowed */}else if(next.isEmpty()&&newUser.equals(oldUser)){JOptionPane.showMessageDialog(this,"Enter a new username or a new password.");return;}
        try(Connection c=DatabaseConnection.getConnection()){try(PreparedStatement verify=c.prepareStatement("SELECT id FROM users WHERE username=? AND password=?")){verify.setString(1,oldUser);verify.setString(2,current);try(ResultSet r=verify.executeQuery()){if(!r.next()){JOptionPane.showMessageDialog(this,"Current password is incorrect.","Authentication failed",JOptionPane.ERROR_MESSAGE);return;}}}
            String sql=next.isEmpty()?"UPDATE users SET username=? WHERE username=?":"UPDATE users SET username=?, password=? WHERE username=?";try(PreparedStatement p=c.prepareStatement(sql)){p.setString(1,newUser);if(next.isEmpty())p.setString(2,oldUser);else{p.setString(2,next);p.setString(3,oldUser);}p.executeUpdate();}Session.setUsername(newUser);ActivityLogger.log("ADMIN_SETTINGS_UPDATED","Username/password settings updated");JOptionPane.showMessageDialog(this,"Admin settings updated. Use the new credentials at next login.");dispose();
        }catch(SQLIntegrityConstraintViolationException ex){JOptionPane.showMessageDialog(this,"That username is already in use.","Duplicate username",JOptionPane.WARNING_MESSAGE);}catch(SQLException ex){JOptionPane.showMessageDialog(this,"Could not update settings: "+ex.getMessage(),"Database Error",JOptionPane.ERROR_MESSAGE);}}
}
